1136	// A delivery is safe to queue: it owns no workspace or observer and becomes a
1137	// no-op when its hub is destroyed. Revision advances at commit(), before a
1138	// consumer can observe the committed native state, rather than at delivery.
1139	class WorkspaceChangeDelivery
1140	{
1141	public:
1142	    WorkspaceChangeDelivery() = default;
1143	
1144	    void deliver()
1145	    {
1146	        if (m_deliver) {
1147	            auto deliver = std::move(m_deliver);
1148	            deliver();
