1159	};
1160	
1161	// This hub is GUI-independent. A concrete workspace mutates authoritative
1162	// state, merges all reasons belonging to that one logical operation, calls
1163	// commit(), and delivers before committing a later mutation. Production uses
1164	// synchronous GUI-thread delivery so a snapshot read by the callback has the
1165	// event's revision. A delivery may be deferred only when the owner guarantees
1166	// that no later mutation can commit first (the teardown test exercises this).
1167	class WorkspaceChangeHub
1168	{
1169	public:
1170	    WorkspaceChangeHub() : m_state(std::make_shared<State>()) {}
1171	    WorkspaceChangeHub(const WorkspaceChangeHub&) = delete;
1172	    WorkspaceChangeHub& operator=(const WorkspaceChangeHub&) = delete;
1173	    ~WorkspaceChangeHub()
1174	    {
1175	        m_state->alive = false;
1176	        m_state->observers.clear();
1177	    }
1178	
1179	    WorkspaceSubscription subscribe(WorkspaceChangedCallback callback)
1180	    {
1181	        const std::uint64_t id = m_state->next_observer_id++;
1182	        m_state->observers.emplace(id, std::move(callback));
1183	        std::weak_ptr<State> weak_state = m_state;
1184	        return WorkspaceSubscription([weak_state, id]() {
1185	            if (auto state = weak_state.lock())
1186	                state->observers.erase(id);
1187	        });
1188	    }
1189	
1190	    void merge(WorkspaceChangeReasons reasons) { m_state->pending |= reasons; }
1191	    bool has_pending() const { return m_state->pending != WorkspaceChangeReasons::None; }
1192	    std::uint64_t revision() const { return m_state->revision; }
1193	
1194	    WorkspaceChangeDelivery commit(ProjectSessionId session)
1195	    {
1196	        if (!has_pending())
1197	            return {};
1198	
1199	        WorkspaceChanged change{session, ++m_state->revision, m_state->pending};
1200	        m_state->pending = WorkspaceChangeReasons::None;
1201	        std::weak_ptr<State> weak_state = m_state;
1202	        return WorkspaceChangeDelivery([weak_state, change]() {
1203	            auto state = weak_state.lock();
1204	            if (!state)
1205	                return;
1206	
1207	            std::vector<std::uint64_t> observer_ids;
1208	            observer_ids.reserve(state->observers.size());
1209	            for (const auto& observer : state->observers)
1210	                observer_ids.emplace_back(observer.first);
1211	
1212	            // Look up each observer immediately before invoking it. This makes
1213	            // removing this or another subscription during dispatch safe.
1214	            for (const std::uint64_t id : observer_ids) {
1215	                if (!state->alive)
1216	                    break;
1217	                const auto observer = state->observers.find(id);
1218	                if (observer == state->observers.end())
1219	                    continue;
1220	                WorkspaceChangedCallback callback = observer->second;
1221	                callback(change);
1222	            }
1223	        });
1224	    }
1225	
1226	    std::optional<WorkspaceChanged> publish(ProjectSessionId session, WorkspaceChangeReasons reasons)
1227	    {
1228	        merge(reasons);
1229	        const std::uint64_t next_revision = m_state->revision + 1;
1230	        WorkspaceChangeDelivery delivery = commit(session);
1231	        if (!delivery)
1232	            return std::nullopt;
1233	        WorkspaceChanged change{session, next_revision, reasons};
1234	        delivery.deliver();
1235	        return change;
1236	    }
1237	
1238	private:
1239	    struct State
1240	    {
1241	        std::uint64_t                                  revision{0};
1242	        std::uint64_t                                  next_observer_id{1};
1243	        WorkspaceChangeReasons                         pending{WorkspaceChangeReasons::None};
1244	        bool                                            alive{true};
1245	        std::map<std::uint64_t, WorkspaceChangedCallback> observers;
1246	    };
1247	
1248	    std::shared_ptr<State> m_state;
1249	};
