118	    void on_double_click(wxMouseEvent&)
119	    {
120	        // wx sends down/up before the double click, so a drag may be open.
121	        end_drag();
122	        m_callbacks.toggle();
123	    }
124	
125	    void on_motion(wxMouseEvent& event)
126	    {
127	        if (!m_dragging || !HasCapture())
128	            return;
129	        const int pointer_x = ClientToScreen(event.GetPosition()).x;
130	        // A drag only ever sizes the pane; it stops at the minimum width and
131	        // never closes it. Closing is deliberate -- the header button or a
132	        // double click on this divider -- because a drag that closed the pane
133	        // on its own would take the conversation off the screen as a side
134	        // effect of aiming for a narrow one.
135	        m_callbacks.set_width(m_drag_origin_width + m_drag_origin_x - pointer_x);
136	    }
137	
138	    void end_drag()
139	    {
140	        if (!m_dragging)
141	            return;
142	        m_dragging = false;
143	        if (HasCapture())
144	            ReleaseMouse();
145	        Refresh();
146	    }
147	
148	    const ShellTheme& m_theme;
149	    Callbacks m_callbacks;
150	    bool m_hovered{false};
151	    bool m_dragging{false};
152	    int m_drag_origin_x{0};
153	    int m_drag_origin_width{0};
154	};
