164	ShellController::ShellController()
165	{
166	    Bind(wxEVT_TIMER, [this](wxTimerEvent&) {
167	        if (m_autosave) {
168	            m_autosave->tick();
169	            const std::string head = m_autosave->current_version();
170	            if (head != m_timeline_version_head) {
171	                m_timeline_version_head = head;
172	                if (m_agent_pane)
173	                    m_agent_pane->web_view().host().refresh_page_state();
174	            }
175	            const std::string key = std::to_string(int(m_autosave->state())) + m_autosave->error();
176	            if (key != m_autosave_status_key && m_status_row != nullptr) {
177	                m_autosave_status_key = key;
178	                m_status_row->refresh();
179	                if (m_autosave->state() == Workspace::ProjectAutosave::State::Saved &&
180	                    m_home != nullptr && m_home->IsShownOnScreen())
181	                    m_home->refresh();
182	            }
183	        }
184	        if (m_status_row != nullptr && m_frame != nullptr) {
185	            const wxString title = m_status_row->project_summary().BeforeFirst('\n');
186	            if (m_frame->GetTitle() != title) {
187	                m_frame->SetTitle(title);
188	                m_frame->update_title_colour_after_set_title();
189	            }
190	        }
191	        if (!m_agent_pane) return;
192	        auto& host = m_agent_pane->web_view().host();
193	        host.pump_stream();
194	        host.pump_tools();
195	        host.pump_setup();
196	    }, m_runtime_timer.GetId());
197	}
198	
199	ShellController::~ShellController()
200	{
201	    m_runtime_timer.Stop();
202	    if (m_installed)
203	        uninstall();
204	}
205	
206	void ShellController::install(MainFrame& frame, Notebook& tabpanel, wxSizer& main_sizer)
207	{
208	    if (m_installed)
209	        throw std::runtime_error("the JusPrin shell is already installed");
210	
211	    Plater* plater = frame.plater();
212	    if (plater == nullptr)
213	        throw std::runtime_error("the Plater is not constructed");
214	    if (tabpanel.FindPage(plater) != MainFrame::tp3DEditor)
215	        throw std::runtime_error("the Prepare page is not where the shell expects it");
216	    if (main_sizer.GetItem(&tabpanel) == nullptr)
217	        throw std::runtime_error("the tab panel is not in the main layout");
218	
219	    // The design tokens were loaded once, at startup, by the brand palette.
220	    // Checked before touching any layout so a broken resource bundle leaves
221	    // the stock presentation untouched.
222	    m_theme = brand_theme();
223	    if (m_theme == nullptr)
224	        throw std::runtime_error("the JusPrin design tokens did not load; the brand palette logged why");
225	
226	    m_frame     = &frame;
227	    m_saved_frame_title = frame.GetTitle();
228	    m_tabpanel  = &tabpanel;
229	    m_main_sizer = &main_sizer;
230	    m_plater    = plater;
231	
232	    // Saved before any mutation so a partial-install rollback restores the
233	    // real prior state, not a default.
234	    m_saved_collapse_toolbar_enabled = plater->get_collapse_toolbar().is_enabled();
235	    m_saved_auto_preview_after_slice = plater->auto_preview_after_slice();
236	    m_saved_show_config_wizard_on_startup = wxGetApp().show_config_wizard_on_startup;
237	
238	    try {
239	        m_workspace = std::make_unique<Workspace::OrcaWorkspaceAdapter>(*plater);
240	
241	        // Conversation state, stored inside the project's
242	        // auxiliary directory and mirrored to a per-project local recovery
243	        // store under the application data dir.
244	        Agent::ProjectPersistence::Config persistence_config;
245	        persistence_config.recovery_root = (boost::filesystem::path(data_dir()) / "jusprin" / "recovery").string();
246	        persistence_config.managed_root = (boost::filesystem::path(data_dir()) / "jusprin" / "projects").string();
247	        m_persistence = std::make_unique<Agent::ProjectPersistence>(*m_workspace, std::move(persistence_config));
248	
249	        Agent::AgentRuntime agent = Agent::load_agent_runtime(wxGetApp().app_config);
250	
251	        m_status_row = new StatusRow(&frame, *m_theme, *plater, tabpanel, *m_persistence);
252	        m_agent_pane = new AgentPane(&frame, *m_theme, *m_workspace, *m_persistence, agent.availability,
253	                                     std::move(agent.service), std::move(agent.setup),
254	                                     (boost::filesystem::path(data_dir()) / "jusprin" / "mcp.json").string());
255	        m_agent_pane_preferred_width = frame.FromDIP(m_theme->metrics().agent_pane.min_width);
256	        m_agent_resize_handle = new AgentPaneResizeHandle(
257	            &frame, *m_theme,
258	            AgentPaneResizeHandle::Callbacks{
259	                [this] { return m_agent_pane == nullptr ? 0 : m_agent_pane->GetSize().x; },
260	                [this](int width) { request_agent_pane_width(width); },
261	                [this] { toggle_agent_pane(); }});
262	        m_status_row->set_agent_pane_toggle([this] { toggle_agent_pane(); });
263	        m_status_row->set_agent_pane_collapsed(m_agent_pane_collapsed);
