#pragma once

#include <wx/colour.h>
#include <wx/font.h>

#include <array>
#include <optional>
#include <string>

namespace Slic3r::GUI::JusPrin {

// Semantic colors for one appearance mode, resolved from
// resources/jusprin/ui/design-tokens.json. That file is the authoritative
// source; this struct only carries the values the shell consumes.
struct ShellPalette
{
    wxColour surface_canvas;
    wxColour surface_subtle;
    wxColour surface_raised;
    wxColour surface_selected;
    wxColour text_primary;
    wxColour text_secondary;
    wxColour text_on_action;
    wxColour border_subtle;
    wxColour border_strong;
    wxColour border_focus;
    wxColour action_primary;
    wxColour action_primary_hover;
    wxColour action_primary_pressed;
    wxColour action_primary_text;
    wxColour action_secondary;
    wxColour action_secondary_hover;
    wxColour action_secondary_pressed;
    wxColour action_secondary_text;
    wxColour action_secondary_border;
    wxColour action_disabled;
    wxColour action_disabled_text;
    wxColour status_warning;
    wxColour status_success;
    wxColour status_success_on_action;
    wxColour status_danger;
    wxColour overlay_scrim;
    // elevation.medium's shadow colour, with this mode's opacity as alpha.
    wxColour elevation_medium;
    // The 3D axis colours, the same in both modes because they name the same
    // handles: a red X, a green Y and a blue Z.
    wxColour axis_x;
    wxColour axis_y;
    wxColour axis_z;
};

// The text roles the token file defines under typography.roles.
enum class TextRole { PageTitle, Section, Body, BodyBold, BodySmall, BodySmallBold, Label, LabelBold, Metadata, MetadataBold };
constexpr size_t kTextRoleCount = 10;

// The numbers behind one text role. Sizes are DIP; weight is 400 or 700.
struct TypeStyle
{
    int size{0};
    int line_height{0};
    int weight{0};
};

// One entry of component.button. Each recipe names only some of these
// fields; the ones it leaves out stay 0.
struct ButtonRecipe
{
    int min_width{0};
    int width{0};
    int height{0};
    int min_height{0};
    int padding_x{0};
    int padding_y{0};
    int icon_size{0};
    int radius{0};
    std::optional<TextRole> text_role;
};

struct ButtonMetrics
{
    ButtonRecipe compact;
    ButtonRecipe window;
    ButtonRecipe choice;
    ButtonRecipe parameter;
    ButtonRecipe icon;
    ButtonRecipe expanded;
    ButtonRecipe secondary;
    ButtonRecipe primary;
};

struct ChipMetrics      { int height{0}; int radius{0}; };
struct MenuRowMetrics   { int height{0}; int radius{0}; int side_inset{0}; };
struct PopoverMetrics   { int padding_y{0}; int row_gap{0}; int radius{0}; };
struct StatusRowMetrics { int height{0}; };
struct AgentPaneMetrics {
    int min_width{0};
    int workspace_min_width{0};
    int resize_handle_width{0};
    int resize_handle_line_width{0};
};
// A colour cell of the filament menu: the swatch, the gaps around the grid,
// and how a cell is drawn at rest and as the slot's current colour.
struct SwatchMetrics
{
    int size{0};
    int radius{0};
    int gap{0};                // between cells
    int caption_gap{0};        // under the grid's caption
    int inset{0};              // swatch inside its cell, at rest
    int current_inset{0};      // ... when it is the slot's colour
    int ring_width{0};         // edge at rest
    int current_ring_width{0}; // ring of the slot's colour
    int glyph_width{0};        // the "+" cell's stroke
};
// The chip's row of filament-slot dots.
struct SlotDotMetrics
{
    int size{0};
    int compact_size{0}; // when more slots are in use than fit at full size
    int gap{0};
    int compact_gap{0};
    int label_gap{0};    // from the last dot to the label
    int faded_alpha{0};  // 0-255: a slot the plate does not print with
};
// The keyboard focus ring every focusable control draws.
struct FocusMetrics     { int width{0}; int offset{0}; };
// Home's printers column, which the printer conversation takes over while it
// is open, so the two are the same width.
struct PrinterCardMetrics { int column_width{0}; int radius{0}; };

// A drop shadow's geometry; its colour differs by mode and lives in ShellPalette.
struct ElevationMetrics { int offset_x{0}; int offset_y{0}; int blur{0}; int spread{0}; };

// The numeric tool panel's parts: a value field with an optional unit, the
// coordinate-space select, the uniform-scale checkbox, one row of the form,
// and the panel that holds them.
struct FieldMetrics     { int height{0}; int radius{0}; int padding_x{0}; int min_width{0};
                          std::optional<TextRole> text_role; std::optional<TextRole> unit_text_role; };
struct SelectMetrics    { int height{0}; int radius{0}; int padding_x{0}; int chevron_size{0};
                          std::optional<TextRole> text_role; };
struct CheckboxMetrics  { int size{0}; int radius{0}; int glyph_size{0}; int label_gap{0};
                          std::optional<TextRole> text_role; };
struct FormRowMetrics   { int height{0}; int gap{0}; int label_width{0}; std::optional<TextRole> text_role; };
struct ToolPanelMetrics { int padding{0}; int row_gap{0}; int radius{0}; int min_width{0};
                          std::optional<TextRole> title_text_role; };

// Geometry from the token file's dimension and component sections. Every
// value is DIP; callers wrap it in FromDIP().
struct ShellMetrics
{
    int radius_standard{0};
    int radius_compact{0};
    int radius_container{0};
    int radius_window{0};
    int radius_pill{0};

    // The spacing scale, named by its step: space_2 is dimension.space["2"].
    int space_1{0};
    int space_2{0};
    int space_3{0};
    int space_4{0};
    int space_5{0};
    int space_6{0};
    int space_8{0};
    int space_10{0};
    int space_12{0};

    ElevationMetrics elevation_medium;

    ButtonMetrics    button;
    FieldMetrics     field;
    SelectMetrics    select;
    CheckboxMetrics  checkbox;
    FormRowMetrics   form_row;
    ToolPanelMetrics tool_panel;
    ChipMetrics      chip;
    MenuRowMetrics   menu_row;
    PopoverMetrics   popover;
    StatusRowMetrics status_row;
    AgentPaneMetrics agent_pane;
    SwatchMetrics    swatch;
    SlotDotMetrics   slot_dot;
    FocusMetrics     focus;
    PrinterCardMetrics  printer_card;
};

class ShellTheme
{
public:
    // Loads both semantic palettes, the metrics and the text roles from the
    // packaged token file. Throws std::runtime_error when the file is missing
    // or malformed so the caller can fall back to the standard Orca
    // presentation. Needs no wx initialisation.
    static ShellTheme load_from_resources();

    const ShellPalette& palette(bool dark) const { return dark ? m_dark : m_light; }
    const ShellMetrics& metrics() const { return m_metrics; }
    const TypeStyle&    type_style(TextRole role) const { return m_type_styles[size_t(role)]; }

    // The wxFont for a role, built once on first use through OrcaSlicer's
    // Label::sysFont so it carries the same face as the rest of the
    // application, then sized so the role's DIP size is its em on every
    // platform (sysFont's own point scaling rounds the token off on Windows
    // and Linux). Requires wx to be initialised.
    const wxFont& font(TextRole role) const;

private:
    ShellPalette m_light;
    ShellPalette m_dark;
    ShellMetrics m_metrics;
    std::array<TypeStyle, kTextRoleCount> m_type_styles{};
    mutable std::array<wxFont, kTextRoleCount> m_fonts{};
};

} // namespace Slic3r::GUI::JusPrin

