        line({{6,14},{10,14}}); line({{8,11},{8,14}});
        break;
    case HeaderIcon::More:
        gc.SetBrush(wxBrush(color));
        for (int i = 0; i < 3; ++i) gc.DrawEllipse(3 + i * 4, 7, 1.5, 1.5);
        break;

