            gc.SetPen(wxPen(p.border_subtle, 1));
            gc.SetBrush(*wxTRANSPARENT_BRUSH);
            gc.DrawRoundedRectangle(button.x + 0.5, button.y + 0.5, button.width - 1, button.height - 1,
